import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0010: The Paddock: artifact previews over a custom transcript","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0010-paddock-artifacts.md","filePath":"adrs/0010-paddock-artifacts.md","lastUpdated":1789092097000}`),u={name:`adrs/0010-paddock-artifacts.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[15]||=a(`<h1 id="adr-0010-the-paddock-artifact-previews-over-a-custom-transcript" tabindex="-1">ADR-0010: The Paddock: artifact previews over a custom transcript <a class="header-anchor" href="#adr-0010-the-paddock-artifact-previews-over-a-custom-transcript" aria-label="Permalink to “ADR-0010: The Paddock: artifact previews over a custom transcript”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-29</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>JB wants rich previews: syntax-highlighted code, rendered diagrams and charts, live HTML, and eventually running code. The question arose as &quot;should we adopt <a href="https://github.com/EnesKaraosman/SwiftyChat" target="_blank" rel="noreferrer">SwiftyChat</a>?&quot; Evaluated fairly: it has macOS 14+ support (since 2.7.0) and is actively maintained, but it is a <em>messenger</em> kit (carousels, quick replies, contacts). It has no streaming-token model, no markdown pipeline, no thinking disclosures, no tool cards, and no artifact rendering, which is the actual ask. Swapping frameworks pays a rebuild tax toward none of the goal.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2>`,5),c(`p`,null,[c(`strong`,null,[l[1]||=i(`Transcript stays custom (reaffirms ADR-0002). The ask becomes a new surface: the `,-1),r(m,{term:`paddock`},{default:n(()=>[...l[0]||=[i(`Paddock`,-1)]]),_:1})]),l[2]||=i(`, where the goat's creations run around.`,-1)]),c(`ul`,null,[l[14]||=a(`<li><strong>Phase 1, rich code in-transcript:</strong> <a href="https://github.com/appstefan/HighlightSwift" target="_blank" rel="noreferrer">HighlightSwift</a> (highlight.js via JavaScriptCore, 50+ languages, fully offline) plugged into MarkdownUI&#39;s code-block style. Header row: language chip, Copy, Save…, Open in Paddock. Highlighting runs on completed messages only (the streaming perf rule stands).</li><li><strong>Phase 2, the Paddock pane:</strong> lives in the inspector slot (artifact open → Paddock; closed → info inspector). Fenced <code>html</code>/<code>svg</code>/<code>mermaid</code>/<code>markdown</code> blocks and any code block open there. Renderers: HTML/SVG in a <code>WKWebView</code> with <code>websiteDataStore = .nonPersistent()</code>; <strong>Mermaid via <code>mermaid.min.js</code> (11.x) bundled as an app resource</strong>, no CDN, the Airplane Mode Guarantee holds; markdown natively via MarkdownUI. Export via <code>NSSavePanel</code>.</li>`,2),c(`li`,null,[l[8]||=c(`strong`,null,`Phase 3, Run (deferred, designed):`,-1),l[9]||=i(` ▶ on scripts (python3 / zsh / swift) executes via `,-1),l[10]||=c(`code`,null,`Process`,-1),l[11]||=i(` behind the `,-1),c(`strong`,null,[l[5]||=i(`same Deny / Allow Once / Always gate as `,-1),r(m,{term:`mcp`},{default:n(()=>[...l[3]||=[i(`MCP`,-1)]]),_:1}),l[6]||=i(),r(m,{term:`tool`},{default:n(()=>[...l[4]||=[i(`tools`,-1)]]),_:1})]),l[12]||=i(` (ADR-0006). Code execution is a permission surface, never a free pass. Output `,-1),r(m,{term:`streaming`},{default:n(()=>[...l[7]||=[i(`streams`,-1)]]),_:1}),l[13]||=i(` into the pane.`,-1)])]),l[16]||=a(`<h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Model-authored HTML renders in-app: mitigated by non-persistent web storage, no credentials in the app to steal, local-only posture (ADR-0007); the webview is a viewer, not a browser.</li><li>Two additions: HighlightSwift (SPM) and the 3.4MB mermaid asset. The AGENT.md size-rule exception now covers <code>App/Resources</code> alongside the icon.</li><li>MarkdownUI&#39;s code-block rendering is now ours to maintain, and ours to make excellent.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>SwiftyChat swap (rejected: messenger-shaped, zero artifact features, rebuild tax), native Swift Charts renderer for a chart JSON spec (deferred: mermaid + HTML cover it), CDN-loaded mermaid (rejected: violates the Airplane Mode Guarantee), separate artifact window (deferred: inspector slot first, window promotion later if wanted).</p>`,4)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};